import { ArrowUpRight } from "lucide-react";
import { ViewTransition } from "react";

const links = [{ label: "Instagram", href: "https://instagram.com" }, { label: "LinkedIn", href: "https://linkedin.com" }, { label: "GitHub", href: "https://github.com" }];

export function Footer1({ brand = "FORM / FIELD", email = "hello@example.com", className = "" }: { brand?: string; email?: string; className?: string }) {
  return <ViewTransition enter="morph-enter" exit="morph-exit" default="none"><footer className={`w-full border border-secondary-foreground/15 bg-secondary px-6 py-10 text-secondary-foreground sm:px-10 sm:py-14 ${className}`}>
    <div className="grid gap-10 md:grid-cols-[1fr_auto] md:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.24em] text-primary">Have a good one in mind?</p><a href={`mailto:${email}`} className="mt-3 inline-flex items-center gap-2 text-3xl font-light tracking-tight hover:text-primary focus-visible:outline-2">Let&apos;s make it real <ArrowUpRight size={22} aria-hidden="true" /></a><p className="mt-3 text-sm text-secondary-foreground/60">Independent by nature. Collaborative by design.</p></div><nav aria-label="Social links" className="flex flex-wrap gap-x-6 gap-y-2">{links.map(link => <a key={link.label} href={link.href} target="_blank" rel="noreferrer" className="font-mono text-xs text-secondary-foreground/70 underline-offset-4 hover:text-secondary-foreground hover:underline focus-visible:outline-2">{link.label} ↗</a>)}</nav></div>
    <div className="mt-10 flex flex-wrap justify-between gap-3 border-t border-secondary-foreground/15 pt-4 font-mono text-[10px] uppercase tracking-widest text-secondary-foreground/50"><span>© {new Date().getFullYear()} {brand}</span><a href="#top" className="hover:text-secondary-foreground">Back to top ↑</a></div>
  </footer></ViewTransition>;
}
